# streamlit_app.py
# ------------------------------------------------------------
# Streamlit front‑end for the FreshCart project.
# It re‑uses the JSON files generated by model/train.py:
#   - model/sample_users.json
#   - model/sample_user_features.json  (top‑10 predictions per user)
#   - model/dataset_stats.json
# No raw CSV files are required – everything runs from precomputed JSON.
# ------------------------------------------------------------

import json
import pathlib
import pandas as pd
import streamlit as st

# ------------------------------------------------------------------
# Paths
BASE_DIR = pathlib.Path(__file__).parent.resolve()
MODEL_DIR = BASE_DIR / "model"

# ------------------------------------------------------------------
# Helper: load JSON (cached) – takes a string path for hashability
@st.cache_data
def load_json(path_str: str):
    path = pathlib.Path(path_str)
    if not path.exists():
        st.error(f"Missing file: {path}")
        return None
    with path.open(encoding="utf-8") as f:
        return json.load(f)

# ------------------------------------------------------------------
# Load sample users (for the dropdown)
@st.cache_data
def load_sample_users():
    users = load_json(str(MODEL_DIR / "sample_users.json"))
    if not users:
        return []
    return users  # list of dicts with user_id and order_count

# Load precomputed predictions for all demo users
@st.cache_data
def load_all_predictions():
    return load_json(str(MODEL_DIR / "sample_user_features.json")) or {}

# Load dataset stats
@st.cache_data
def load_dataset_stats():
    return load_json(str(MODEL_DIR / "dataset_stats.json")) or {}

# ------------------------------------------------------------------
# Page layout
st.set_page_config(page_title="FreshCart – AI Grocery", layout="wide")
st.title("🛒 FreshCart – Online Grocery + AI Next‑Basket")
st.caption("LightGBM model trained on real Instacart data (3.4M+ orders), rendered with Streamlit.")

# --------------------------------------------------------------
# 1️⃣ User selector
users = load_sample_users()
if not users:
    st.error("Could not load sample users. Make sure `model/sample_users.json` exists.")
    st.stop()

# Build a nice label for each user
user_options = {f"Customer #{u['user_id']} ({u['order_count']} past orders)": u['user_id'] for u in users}
selected_label = st.selectbox("👤 Choose a customer", list(user_options.keys()))
selected_user_id = user_options[selected_label]

# --------------------------------------------------------------
# 2️⃣ Show dataset stats (expandable)
with st.expander("📊 Dataset & model statistics", expanded=False):
    stats = load_dataset_stats()
    if stats:
        col1, col2, col3 = st.columns(3)
        col1.metric("Total Orders", f"{stats.get('total_orders', 0):,}")
        col2.metric("Total Users", f"{stats.get('total_users', 0):,}")
        col3.metric("Total Products", f"{stats.get('total_products', 0):,}")

        col4, col5, col6 = st.columns(3)
        metrics = stats.get("metrics", {})
        col4.metric("Precision@10", f"{metrics.get('precision_at_10', 0) * 100:.2f}%")
        col5.metric("Recall@10", f"{metrics.get('recall_at_10', 0) * 100:.2f}%")
        col6.metric("Reorder Rate", f"{stats.get('overall_reorder_rate', 0) * 100:.2f}%")

        # Top 10 products chart
        top10 = stats.get("top_10_products", [])
        if top10:
            st.subheader("🏆 Top 10 Most Ordered Products")
            top10_df = pd.DataFrame(top10)
            st.bar_chart(top10_df.set_index("product_name")["order_count"])

        # Orders by weekday chart
        orders_by_weekday = stats.get("orders_by_weekday", {})
        if orders_by_weekday:
            st.subheader("📅 Orders by Day of Week")
            dow_df = pd.DataFrame(list(orders_by_weekday.items()), columns=["Day", "Orders"])
            st.bar_chart(dow_df.set_index("Day")["Orders"])

        # Orders by hour chart
        orders_by_hour = stats.get("orders_by_hour", {})
        if orders_by_hour:
            st.subheader("🕐 Orders by Hour of Day")
            hour_df = pd.DataFrame(
                [(int(h), v) for h, v in orders_by_hour.items()],
                columns=["Hour", "Orders"]
            ).sort_values("Hour")
            st.bar_chart(hour_df.set_index("Hour")["Orders"])

        # Feature importance
        feat_imp = stats.get("feature_importance", {})
        if feat_imp:
            st.subheader("🧠 Feature Importance (LightGBM Gain)")
            fi_df = pd.DataFrame(
                list(feat_imp.items()), columns=["Feature", "Importance"]
            ).sort_values("Importance", ascending=False)
            st.bar_chart(fi_df.set_index("Feature")["Importance"])

# --------------------------------------------------------------
# 3️⃣ Top‑10 predictions for the selected user
all_predictions = load_all_predictions()
user_key = str(selected_user_id)
preds = all_predictions.get(user_key, [])

if not preds:
    st.info("No predictions available for this user.")
else:
    st.subheader(f"🔮 Top‑10 Predictions for Customer #{selected_user_id}")

    # Create a DataFrame for nicer display
    pred_df = pd.DataFrame(preds)

    # Show a simple probability bar
    def prob_bar(p):
        pct = round(p * 100, 1)
        filled = int(p * 20)
        return f"{pct}% " + "▮" * filled + "▯" * (20 - filled)

    pred_df["probability_bar"] = pred_df["probability"].apply(prob_bar)

    # Build a reason column from features
    pred_df["reason"] = pred_df.apply(
        lambda r: f"Bought in {r['up_purchase_count']} of {r['user_total_orders']} past orders",
        axis=1
    )

    display = pred_df[["product_id", "probability_bar", "reason"]].copy()
    display.rename(columns={
        "product_id": "Product ID",
        "probability_bar": "Reorder Probability",
        "reason": "Reason"
    }, inplace=True)
    st.dataframe(display, use_container_width=True)

    if st.button("🛒 Add all predicted items to cart"):
        st.success("All recommended items added to your virtual cart!")

# --------------------------------------------------------------
# 4️⃣ Model information
st.divider()
st.subheader("ℹ️ About This Model")
st.markdown("""
- **Algorithm**: LightGBM (Gradient Boosted Decision Trees)
- **Training Data**: Real Instacart Market Basket dataset (3.4M+ orders, 206K+ users, 49K+ products)
- **Features**: 12 engineered user‑product features (purchase count, recency, reorder rate, cart position, etc.)
- **Evaluation**: Precision@10 and Recall@10 on 2,000 unseen validation users (GroupShuffleSplit)
- **Focus**: Predicts which previously‑purchased products a customer is most likely to reorder
""")

st.caption("💡 This Streamlit app reads pre‑computed JSON predictions generated by `model/train.py`. "
           "No raw CSV files are required for deployment.")
